 "content": "from collections import Counter
from math import inf

def _dominant_line(values):
    counts = Counter(values)
    color, n = counts.most_common(1)[0]
    return color, n / len(values)

def _regularity(indices):
    if len(indices) < 2:
        return 0.0
    gaps = [b - a for a, b in zip(indices, indices[1:])]
    if len(gaps) == 1:
        return 0.8
    mode, n = Counter(gaps).most_common(1)[0]
    return n / len(gaps)

def transform(grid):
    h, w = len(grid), len(grid[0])
    row_doms = [_dominant_line(row) for row in grid]
    col_doms = [_dominant_line([grid[r][c] for r in range(h)]) for c in range(w)]
    # Separator stripes are highly uniform and recur periodically in both axes.
    choices = []
    colors = set(c for c, frac in row_doms + col_doms if frac >= .78)
    for color in colors:
        rs = [i for i, (c, f) in enumerate(row_doms) if c == color and f >= .78]
        cs = [i for i, (c, f) in enumerate(col_doms) if c == color and f >= .78]
        if len(rs) < 2 or len(cs) < 2:
            continue
        rr, cr = _regularity(rs), _regularity(cs)
        # Prefer color whose stripe indices form the cleanest repeated lattice.
        score = rr + cr + .05 * (min(len(rs), 8) + min(len(cs), 8))
        choices.append((score, color, rs, cs))
    if not choices:
        return [[Counter(v for row in grid for v in row).most_common(1)[0][0]]]
    _, line_color, rows, cols = max(choices)
    # Underlying tile color is the global mode; separator color should not survive
    # at ordinary intersections in the reduced representation.
    base = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = []
    for r in rows[:-1]:
        out.append([base if grid[r][c] == line_color else grid[r][c] for c in cols[:-1]])
    return out
"
}

