 "content": "from collections import Counter

def _dominant(values):
    c, n = Counter(values).most_common(1)[0]
    return c, n / len(values)

def _regular(indices):
    if len(indices) < 2:
        return 0.0
    gaps = [b-a for a,b in zip(indices, indices[1:])]
    return Counter(gaps).most_common(1)[0][1] / len(gaps)

def transform(grid):
    h, w = len(grid), len(grid[0])
    rd = [_dominant(row) for row in grid]
    cd = [_dominant([grid[r][c] for r in range(h)]) for c in range(w)]
    candidates = set(color for color, frac in rd+cd if frac >= .78)
    scored = []
    for color in candidates:
        rows = [i for i,(x,f) in enumerate(rd) if x == color and f >= .78]
        cols = [i for i,(x,f) in enumerate(cd) if x == color and f >= .78]
        if len(rows) >= 2 and len(cols) >= 2:
            score = _regular(rows) + _regular(cols) + .04*(len(rows)+len(cols))
            scored.append((score, color, rows, cols))
    if not scored:
        return [grid[0][:1]]
    _, line, rows, cols = max(scored)
    base = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # These are lattice vertices: retain their marker colors, but replace the
    # ordinary separator color by the color of the repeating tile interior.
    return [[base if grid[r][c] == line else grid[r][c] for c in cols[:-1]]
            for r in rows[:-1]]
