 "content": "from collections import Counter

def _dominant(values):
    color, n = Counter(values).most_common(1)[0]
    return color, n / len(values)

def _regularity(indices):
    if len(indices) < 2:
        return 0.0
    gaps = [b-a for a,b in zip(indices, indices[1:])]
    counts = Counter(gaps)
    return counts.most_common(1)[0][1] / len(gaps)

def transform(grid):
    h, w = len(grid), len(grid[0])
    rd = [_dominant(row) for row in grid]
    cd = [_dominant([grid[r][c] for r in range(h)]) for c in range(w)]
    colors = set(c for c, f in rd + cd if f >= .58)
    options = []
    for color in colors:
        rs = [i for i, (c, f) in enumerate(rd) if c == color and f >= .58]
        cs = [i for i, (c, f) in enumerate(cd) if c == color and f >= .58]
        if len(rs) < 2 or len(cs) < 2:
            continue
        # Separator positions recur at the same interval across both axes.
        score = _regularity(rs) + _regularity(cs) + .025 * (len(rs) + len(cs))
        options.append((score, color, rs, cs))
    if not options:
        return [[Counter(v for row in grid for v in row).most_common(1)[0][0]]]
    _, line_color, rows, cols = max(options)
    values = Counter(v for row in grid for v in row)
    base = max((v for v in values if v != line_color), key=lambda v: values[v])
    return [[base if grid[r][c] == line_color else grid[r][c] for c in cols[:-1]]
            for r in rows[:-1]]
"
}

