    return color, n / len(values)

def transform(grid):
    h, w = len(grid), len(grid[0])
    row_dom = [_dominant(row) for row in grid]
    col_dom = [_dominant([grid[r][c] for r in range(h)]) for c in range(w)]
    candidates = {color for color, frac in row_dom + col_dom if frac >= .60}
    best = None
    for color in candidates:
        rows = [i for i, (c, f) in enumerate(row_dom) if c == color and f >= .60]
        cols = [i for i, (c, f) in enumerate(col_dom) if c == color and f >= .60]
        if len(rows) < 2 or len(cols) < 2:
            continue
        # Repeated stripe spacing identifies the separator color, not the field.
        def regular(ids):
            if len(ids) < 2:
                return 0
            gaps = [b-a for a,b in zip(ids, ids[1:])]
            return Counter(gaps).most_common(1)[0][1] / len(gaps)
        score = regular(rows) + regular(cols) + .025 * (len(rows)+len(cols))
        if best is None or score > best[0]:
            best = (score, color, rows, cols)
    if best is None:
        return [[Counter(v for row in grid for v in row).most_common(1)[0][0]]]
    _, line, rows, cols = best
    freq = Counter(v for row in grid for v in row)
    base = max((v for v in freq if v != line), key=lambda v: freq[v])
    # Each output cell is a crossing of horizontal and vertical separator stripes.
    # Omit the trailing stripe in both axes; ordinary separator color becomes field color.
    return [[base if grid[r][c] == line else grid[r][c] for c in cols[:-1]]
            for r in rows[:-1]]
