 "content": "from collections import Counter

def _dominant(values):
    color, n = Counter(values).most_common(1)[0]
    return color, n / len(values)

def _stripe_groups(dominants, threshold=0.74):
    groups = {}
    for i, (color, frac) in enumerate(dominants):
        if frac >= threshold:
            groups.setdefault(color, []).append(i)
    return groups

def _period_score(indices):
    if len(indices) < 2:
        return -1.0
    gaps = [b-a for a,b in zip(indices, indices[1:])]
    counts = Counter(gaps)
    gap, count = counts.most_common(1)[0]
    # Prefer regular lattice spacing, penalizing non-modal gaps.
    return count / len(gaps) - 0.02 * (max(gaps) - min(gaps))

def transform(grid):
    h, w = len(grid), len(grid[0])
    rd = [_dominant(row) for row in grid]
    cd = [_dominant([grid[r][c] for r in range(h)]) for c in range(w)]
    rg, cg = _stripe_groups(rd), _stripe_groups(cd)
    choices = []
    for color in set(rg) & set(cg):
        rows, cols = rg[color], cg[color]
        if len(rows) < 2 or len(cols) < 2:
            continue
        score = _period_score(rows) + _period_score(cols) + .01 * min(len(rows), len(cols))
        choices.append((score, color, rows, cols))
    if not choices:
        # Fallback: choose most common color among row/column dominant colors.
        color = Counter(c for c, f in rd + cd if f >= .74).most_common(1)[0][0]
        rows = rg.get(color, list(range(0, h, 2)))
        cols = cg.get(color, list(range(0, w, 2)))
    else:
        _, color, rows, cols = max(choices)
    counts = Counter(v for row in grid for v in row)
    base = max((v for v in counts if v != color), key=lambda v: counts[v])
    # Crossings encode cells of the reduced grid; the ordinary separator color
    # stands for the repeated tile's background color.
    return [[base if grid[r][c] == color else grid[r][c]
             for c in cols[:-1]] for r in rows[:-1]]
"
}

