def transform(grid):
    h, w = len(grid), len(grid[0])
    # Separator line color is the patterned background of the large field;
    # rows and columns dominated by it are lattice intersections.
    def dominant(values):
        c, n = Counter(values).most_common(1)[0]
        return c, n / len(values)
    row_d = [dominant(row) for row in grid]
    col_d = [dominant([grid[r][c] for r in range(h)]) for c in range(w)]
    possible = set(c for c, frac in row_d + col_d if frac > 0.72)
