        cs = [i for i, (c, f) in enumerate(col_d) if c == color and f > 0.72]
        if len(rs) >= 2 and len(cs) >= 2:
            candidates.append((len(rs) * len(cs), color, rs, cs))
    if candidates:
        _, sep, rs, cs = max(candidates)
    else:
        return [[Counter(v for row in grid for v in row).most_common(1)[0][0]]]
    # Main underlying tile color is the most frequent non-separator color.
    freq = Counter(v for row in grid for v in row if v != sep)
    base = freq.most_common(1)[0][0]
    # Output keeps all non-terminal intersections; omitted terminal line is the
    # outer margin. The separator color at a junction means the base field color.
    return [[base if grid[r][c] == sep else grid[r][c] for c in cs[:-1]]
            for r in rs[:-1]]
